<section class="form-page wrap">
  <a class="back-link" href="?page=discover">← Back to reviewed dishes</a>
  <div class="form-layout"><div class="form-aside"><div class="eyebrow"><span class="eyebrow-line"></span> <?= $editingReview ? 'Your contribution' : 'Add your voice' ?></div><h1><?= $editingReview ? 'Polish your' : 'Tell us what' ?><br><?= $editingReview ? 'review.' : 'was <span class="serif-word">delicious.</span>' ?></h1><p>The details you share help someone else make a great choice. Keep it real, specific, and kind.</p><div class="aside-tip"><span>✦</span><p><strong>A little tip</strong><br>Natural light and a close-up make the dish look its best.</p></div></div>
  <form class="panel-form" action="" method="post" enctype="multipart/form-data" data-review-form>
    <input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="<?= $editingReview ? 'update_review' : 'review' ?>"><?php if ($editingReview): ?><input type="hidden" name="review_id" value="<?= (int) $editingReview['id'] ?>"><?php endif; ?>
    <div class="field"><label for="restaurant">Restaurant <span>*</span></label><select id="restaurant" name="restaurant_id" required><option value="">Choose a restaurant</option><?php foreach ($restaurants as $restaurant): ?><option value="<?= (int) $restaurant['id'] ?>" <?= $editingReview && (int) $editingReview['restaurant_id'] === (int) $restaurant['id'] ? 'selected' : '' ?>><?= e($restaurant['name']) ?> · <?= e($restaurant['neighborhood']) ?></option><?php endforeach; ?></select></div>
    <div class="field"><label for="dish">Dish name <span>*</span></label><input id="dish" name="dish_name" type="text" placeholder="What did you order?" maxlength="100" value="<?= e($editingReview['dish_name'] ?? '') ?>" required></div>
    <fieldset class="field rating-field"><legend>Your rating <span>*</span></legend><div class="rating-picker" role="radiogroup" aria-label="Your rating from one to five stars"><?php for ($star = 1; $star <= 5; $star++): ?><label class="<?= $editingReview && (int) $editingReview['rating'] >= $star ? 'selected' : '' ?>"><input type="radio" name="rating" value="<?= $star ?>" <?= $editingReview && (int) $editingReview['rating'] === $star ? 'checked' : '' ?> required><span aria-hidden="true">★</span><span class="sr-only"><?= $star ?> <?= $star === 1 ? 'star' : 'stars' ?></span></label><?php endfor; ?><span class="rating-hint">Tap a star to rate</span></div></fieldset>
    <div class="field"><div class="field-label-row"><label for="body">What stood out? <span>*</span></label><span class="char-count" data-char-count><?= strlen($editingReview['body'] ?? '') ?> / 500</span></div><textarea id="body" name="body" rows="5" minlength="20" maxlength="500" placeholder="Tell us about the taste, texture, presentation, and what you’d tell a friend…" required><?= e($editingReview['body'] ?? '') ?></textarea><small>Be specific—thoughtful details help your review stand out.</small></div>
    <div class="field"><label for="photo">Add a photo <span class="optional">Optional</span></label><label class="upload-box" for="photo"><span class="upload-icon">＋</span><span><strong><?= $editingReview && $editingReview['photo_path'] ? 'Choose a new photo or keep the current one' : 'Choose a photo' ?></strong><small>JPG or PNG, up to 5 MB</small></span><input id="photo" name="photo" type="file" accept="image/jpeg,image/png"></label></div>
    <div class="form-actions"><a class="text-button" href="?page=discover">Cancel</a><button class="button button-dark" type="submit"><?= $editingReview ? 'Save changes' : 'Submit review' ?> <span>↗</span></button></div>
  </form></div>
</section>
